#!/usr/bin/env node

/**
 * Production capability verification contract.
 *
 * This script intentionally refuses to claim a deployment check when no live
 * Supabase function inventory is supplied. CI should provide a newline- or
 * JSON-based `SUPABASE_DEPLOYED_FUNCTIONS` snapshot generated by
 * `supabase functions list` against the production project.
 */

import fs from 'node:fs';
import path from 'node:path';

const snapshot = process.env.SUPABASE_DEPLOYED_FUNCTIONS;
if (!snapshot) {
  console.error('Missing SUPABASE_DEPLOYED_FUNCTIONS. Generate it from the production Supabase project.');
  process.exit(2);
}

let deployed;
try {
  const parsed = JSON.parse(snapshot);
  deployed = Array.isArray(parsed) ? parsed.map((x) => typeof x === 'string' ? x : x.name).filter(Boolean) : [];
} catch {
  deployed = snapshot.split(/\r?\n/).map((x) => x.trim()).filter(Boolean);
}

const registryPath = path.resolve('src/config/platform-capabilities.ts');
const source = fs.readFileSync(registryPath, 'utf8');
const required = [...source.matchAll(/backedBy:\s*\[([\s\S]*?)\]/g)]
  .flatMap((m) => [...m[1].matchAll(/['"]([^'"]+)['"]/g)].map((x) => x[1]));

const deployedSet = new Set(deployed);
const missing = [...new Set(required)].filter((fn) => !deployedSet.has(fn));

if (missing.length) {
  console.error(`Missing production functions: ${missing.join(', ')}`);
  process.exit(1);
}

console.log(`Capability production contract OK: ${required.length} required functions present.`);
